const { query } = require('../db');
const logger = require('../utils/logger');

const MAX_META_BYTES = parseInt(process.env.ADMIN_AUDIT_META_MAX_BYTES || '', 10) || 50_000;
const MAX_META_STRING = parseInt(process.env.ADMIN_AUDIT_META_MAX_STRING || '', 10) || 2000;
const MAX_META_KEYS = parseInt(process.env.ADMIN_AUDIT_META_MAX_KEYS || '', 10) || 100;
const MAX_META_ARRAY = parseInt(process.env.ADMIN_AUDIT_META_MAX_ARRAY || '', 10) || 100;
const MAX_META_DEPTH = parseInt(process.env.ADMIN_AUDIT_META_MAX_DEPTH || '', 10) || 5;

function sanitizeAuditMeta(meta) {
  if (!meta || typeof meta !== 'object') return {};

  const seen = new WeakSet();

  const sanitize = (value, depth) => {
    if (value === null || value === undefined) return value;
    if (typeof value === 'string') {
      if (value.length <= MAX_META_STRING) return value;
      return `${value.slice(0, MAX_META_STRING)}…`;
    }
    if (typeof value === 'number' || typeof value === 'boolean') return value;
    if (value instanceof Date) return value.toISOString();
    if (Buffer.isBuffer(value)) return `[buffer:${value.length}]`;

    if (Array.isArray(value)) {
      if (depth >= MAX_META_DEPTH) return `[array:${value.length}]`;
      return value.slice(0, MAX_META_ARRAY).map((v) => sanitize(v, depth + 1));
    }

    if (typeof value === 'object') {
      if (depth >= MAX_META_DEPTH) return '[object]';
      if (seen.has(value)) return '[circular]';
      seen.add(value);

      const out = {};
      const keys = Object.keys(value).slice(0, MAX_META_KEYS);
      for (const key of keys) {
        out[key] = sanitize(value[key], depth + 1);
      }
      return out;
    }

    return String(value);
  };

  let sanitized = sanitize(meta, 0);

  try {
    const bytes = Buffer.byteLength(JSON.stringify(sanitized), 'utf8');
    if (bytes <= MAX_META_BYTES) return sanitized;
  } catch (_) {
    // fall through to truncation fallback
  }

  const fallback = {
    truncated: true,
    note: 'audit meta exceeded size limits',
    keys: Object.keys(meta).slice(0, 50),
  };

  try {
    if (meta.before && typeof meta.before === 'object') fallback.before = { id: meta.before.id || null };
    if (meta.after && typeof meta.after === 'object') fallback.after = { id: meta.after.id || null };
  } catch (_) {}

  return fallback;
}

function normalizeRoles(roles) {
  if (!Array.isArray(roles)) return [];
  return roles
    .map((r) => (r || '').toString().trim())
    .filter((r) => r.length > 0);
}

function buildAuditRow({ req, action, entityType, entityId, meta }) {
  const actorUsername = (req?.admin?.username || '').toString().trim();
  const actorRoles = normalizeRoles(req?.admin?.roles);
  const requestIp = req?.ip || null;
  const userAgent = (req?.get && req.get('user-agent')) || req?.headers?.['user-agent'] || null;

  return {
    actorUsername,
    actorRoles,
    action: (action || '').toString(),
    entityType: entityType ? entityType.toString() : null,
    entityId: entityId || null,
    requestIp,
    userAgent: userAgent ? userAgent.toString() : null,
    meta: sanitizeAuditMeta(meta),
  };
}

async function insertAudit({ client, req, action, entityType, entityId, meta }) {
  const row = buildAuditRow({ req, action, entityType, entityId, meta });

  if (!row.actorUsername) {
    throw new Error('Missing admin actor for audit log');
  }

  const exec = client && typeof client.query === 'function' ? client.query.bind(client) : query;

  const res = await exec(
    `INSERT INTO public.admin_audit_logs (
      actor_username,
      actor_roles,
      action,
      entity_type,
      entity_id,
      request_ip,
      user_agent,
      meta
    ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
    RETURNING id, created_at`,
    [
      row.actorUsername,
      row.actorRoles,
      row.action,
      row.entityType,
      row.entityId,
      row.requestIp,
      row.userAgent,
      row.meta,
    ]
  );

  return res.rows[0];
}

/**
 * Record an admin action into `public.admin_audit_logs`.
 *
 * - If a `client` is provided, this will participate in the caller's transaction.
 * - Throws on failure (callers can decide whether to rollback).
 */
async function recordAdminAction({ client, req, action, entityType, entityId, meta }) {
  try {
    return await insertAudit({ client, req, action, entityType, entityId, meta });
  } catch (error) {
    logger.error('adminAuditLogService: failed to record admin audit log', {
      error: error.message,
      action,
      entityType,
      entityId,
      actor: req?.admin?.username,
    });
    throw error;
  }
}

module.exports = {
  recordAdminAction,
};
